-- =============================================================================
-- Migration: Add Rive-Nord & Rive-Sud certified communities (off-island zones)
-- Description: Extends the GMA zone model beyond Montréal island. Adds Laval +
--              agglomération-de-Longueuil and the inner couronnes to
--              public.montreal_borough, tagged with two new zones (rive_nord,
--              rive_sud). derive_zone_from_location() is pure ST_Contains, so it
--              resolves off-island players automatically once the polygons exist.
--              Seeds 4 skill-agnostic certified communities (2 zones × 2 sports),
--              teaches the onboarding auto-join trigger to match skill-NULL
--              communities, and backfills existing off-island onboarded players.
--              Municipal polygons: OpenStreetMap (© OpenStreetMap contributors,
--              ODbL), simplified to ~50 m to keep the migration small.
-- =============================================================================

-- =============================================================================
-- STEP 1: Widen the montreal_borough zone CHECK and add off-island polygons
-- =============================================================================
ALTER TABLE public.montreal_borough DROP CONSTRAINT IF EXISTS montreal_borough_zone_check;
ALTER TABLE public.montreal_borough ADD CONSTRAINT montreal_borough_zone_check
  CHECK (zone IN ('ouest_ile','ouest','centre','nord','est','rive_nord','rive_sud'));

COMMENT ON TABLE public.montreal_borough IS
'Montréal arrondissements + "villes liées" (zones ouest_ile/ouest/centre/nord/est) plus off-island service-area municipalities (rive_nord = Laval & couronne nord, rive_sud = agglomération de Longueuil & couronne sud), each with its GMA zone. Island polygons: Ville de Montréal open data (CC-BY 4.0). Off-island polygons: OpenStreetMap (ODbL), simplified to ~50 m.';

