-- =============================================================================
-- STEP 2: derive_zone_from_location stays pure ST_Contains (refresh comment)
-- =============================================================================
COMMENT ON FUNCTION public.derive_zone_from_location IS
'Returns the GMA zone containing the given location via polygon containment against montreal_borough (island zones ouest_ile/ouest/centre/nord/est + off-island rive_nord/rive_sud). NULL when the point is outside every covered municipality.';

-- =============================================================================
-- STEP 3: Allow off-island zones on network + harden the uniqueness index
-- =============================================================================
ALTER TABLE public.network DROP CONSTRAINT IF EXISTS network_zone_check;
ALTER TABLE public.network ADD CONSTRAINT network_zone_check
  CHECK (zone IS NULL OR zone IN ('ouest_ile','ouest','centre','nord','est','rive_nord','rive_sud'));

-- Recreate with NULLS NOT DISTINCT so skill-agnostic (skill_level IS NULL)
-- communities are still deduped one-per (zone, sport). Default NULLS-DISTINCT
-- would let duplicate rive communities slip past the index.
DROP INDEX IF EXISTS public.uq_network_zone_sport_skill_level;
CREATE UNIQUE INDEX uq_network_zone_sport_skill_level
  ON public.network (zone, sport_id, skill_level) NULLS NOT DISTINCT
  WHERE archived_at IS NULL AND zone IS NOT NULL;

-- =============================================================================
-- STEP 4: Seed the 4 skill-agnostic certified communities
-- =============================================================================
DO $seed$
DECLARE
  v_community_type_id UUID;
  v_creator_id UUID;
  v_tennis_id UUID;
  v_pickleball_id UUID;
  v_nord_hoods TEXT[] := ARRAY['Laval','Terrebonne','Repentigny','Mascouche','Bois-des-Filion','Boisbriand','Sainte-Thérèse','Blainville','Rosemère'];
  v_sud_hoods  TEXT[] := ARRAY['Longueuil','Brossard','Saint-Lambert','Saint-Hubert','Boucherville','Saint-Bruno-de-Montarville','La Prairie','Candiac','Châteauguay'];
  v_nord_desc TEXT := 'Communauté de la Rive-Nord, de Laval à la couronne nord. Quartiers couverts : Laval, Terrebonne, Repentigny, Mascouche, Bois-des-Filion, Boisbriand, Sainte-Thérèse, Blainville, Rosemère. Tous les niveaux bienvenus, du parc municipal au club privé.';
  v_sud_desc  TEXT := 'Communauté de la Rive-Sud, de l''agglomération de Longueuil à la couronne sud. Quartiers couverts : Longueuil, Brossard, Saint-Lambert, Saint-Hubert, Boucherville, Saint-Bruno-de-Montarville, La Prairie, Candiac, Châteauguay. Tous les niveaux bienvenus.';
  -- Cover images from Wikimedia Commons (free to use). Rive-Nord: Pont-Viau /
  -- Rivière des Prairies, © Guilhem Vellut, CC BY 2.0. Rive-Sud: Vieux-Longueuil,
  -- © Hayden Soloviev, CC BY 4.0.
  v_nord_cover TEXT := 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Pont_Viau_%40_Rivi%C3%A8re_des_Prairies_%40_Berge_D%C3%A9lia-T%C3%A9treault_%40_Laval_%2830519343796%29.jpg/1280px-Pont_Viau_%40_Rivi%C3%A8re_des_Prairies_%40_Berge_D%C3%A9lia-T%C3%A9treault_%40_Laval_%2830519343796%29.jpg';
  v_sud_cover  TEXT := 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Vieux-Longueuil.jpg/1280px-Vieux-Longueuil.jpg';
BEGIN
  SELECT id INTO v_community_type_id FROM public.network_type WHERE name = 'community';
  IF v_community_type_id IS NULL THEN RAISE EXCEPTION 'network_type "community" not found'; END IF;

  SELECT id INTO v_tennis_id     FROM public.sport WHERE name = 'tennis';
  SELECT id INTO v_pickleball_id FROM public.sport WHERE name = 'pickleball';
  IF v_tennis_id IS NULL OR v_pickleball_id IS NULL THEN
    RAISE EXCEPTION 'Tennis or Pickleball sport not found';
  END IF;

  SELECT created_by INTO v_creator_id
  FROM public.network
  WHERE name = 'Rallia Beta' AND network_type_id = v_community_type_id
  ORDER BY created_at ASC LIMIT 1;
  IF v_creator_id IS NULL THEN
    SELECT id INTO v_creator_id FROM public.player ORDER BY created_at ASC LIMIT 1;
  END IF;
  IF v_creator_id IS NULL THEN
    RAISE NOTICE 'No player found to use as creator; skipping rive community seed.';
    RETURN;
  END IF;

  -- Rive-Nord — Tennis
  INSERT INTO public.network (network_type_id, name, description, cover_image_url, is_private, is_certified,
    created_by, sport_id, zone, skill_level, neighborhoods, reference_location, min_rating_score_id, max_members, member_count)
  SELECT v_community_type_id, 'Rive-Nord Smash — Tennis', v_nord_desc, v_nord_cover, FALSE, TRUE,
    v_creator_id, v_tennis_id, 'rive_nord', NULL, v_nord_hoods, 'Laval / Centropolis', NULL, NULL, 0
  WHERE NOT EXISTS (SELECT 1 FROM public.network
    WHERE zone='rive_nord' AND sport_id=v_tennis_id AND skill_level IS NULL AND archived_at IS NULL);

  -- Rive-Nord — Pickleball
  INSERT INTO public.network (network_type_id, name, description, cover_image_url, is_private, is_certified,
    created_by, sport_id, zone, skill_level, neighborhoods, reference_location, min_rating_score_id, max_members, member_count)
  SELECT v_community_type_id, 'Rive-Nord Smash — Pickleball', v_nord_desc, v_nord_cover, FALSE, TRUE,
    v_creator_id, v_pickleball_id, 'rive_nord', NULL, v_nord_hoods, 'Laval / Centropolis', NULL, NULL, 0
  WHERE NOT EXISTS (SELECT 1 FROM public.network
    WHERE zone='rive_nord' AND sport_id=v_pickleball_id AND skill_level IS NULL AND archived_at IS NULL);

  -- Rive-Sud — Tennis
  INSERT INTO public.network (network_type_id, name, description, cover_image_url, is_private, is_certified,
    created_by, sport_id, zone, skill_level, neighborhoods, reference_location, min_rating_score_id, max_members, member_count)
  SELECT v_community_type_id, 'Rive-Sud Smash — Tennis', v_sud_desc, v_sud_cover, FALSE, TRUE,
    v_creator_id, v_tennis_id, 'rive_sud', NULL, v_sud_hoods, 'Quartier DIX30, Brossard', NULL, NULL, 0
  WHERE NOT EXISTS (SELECT 1 FROM public.network
    WHERE zone='rive_sud' AND sport_id=v_tennis_id AND skill_level IS NULL AND archived_at IS NULL);

  -- Rive-Sud — Pickleball
  INSERT INTO public.network (network_type_id, name, description, cover_image_url, is_private, is_certified,
    created_by, sport_id, zone, skill_level, neighborhoods, reference_location, min_rating_score_id, max_members, member_count)
  SELECT v_community_type_id, 'Rive-Sud Smash — Pickleball', v_sud_desc, v_sud_cover, FALSE, TRUE,
    v_creator_id, v_pickleball_id, 'rive_sud', NULL, v_sud_hoods, 'Quartier DIX30, Brossard', NULL, NULL, 0
  WHERE NOT EXISTS (SELECT 1 FROM public.network
    WHERE zone='rive_sud' AND sport_id=v_pickleball_id AND skill_level IS NULL AND archived_at IS NULL);
END
$seed$;

-- =============================================================================
-- STEP 5: Teach the auto-join trigger to also match skill-NULL communities.
-- Island zones only have skill-specific rows; rive zones only have a skill-NULL
-- row, so each player still matches exactly one community per sport.
-- =============================================================================
CREATE OR REPLACE FUNCTION public.add_to_zone_communities()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_community_type_id UUID;
  v_zone TEXT;
  v_location extensions.geography;
  v_player_sport RECORD;
  v_player_skill skill_level;
BEGIN
  IF NOT (NEW.onboarding_completed = TRUE
          AND (OLD.onboarding_completed IS DISTINCT FROM TRUE)) THEN
    RETURN NEW;
  END IF;

  SELECT location INTO v_location FROM public.player WHERE id = NEW.id;
  IF NOT FOUND THEN
    RAISE LOG 'Zone auto-join skipped (no player record): user_id=%', NEW.id;
    RETURN NEW;
  END IF;

  v_zone := public.derive_zone_from_location(v_location);
  IF v_zone IS NULL THEN
    RAISE LOG 'Zone auto-join skipped (no resolvable zone): player_id=%', NEW.id;
    RETURN NEW;
  END IF;

  SELECT id INTO v_community_type_id
  FROM public.network_type WHERE name = 'community';

  FOR v_player_sport IN
    SELECT sport_id FROM public.player_sport WHERE player_id = NEW.id
  LOOP
    SELECT rs.skill_level INTO v_player_skill
    FROM public.player_rating_score prs
    JOIN public.rating_score rs ON rs.id = prs.rating_score_id
    JOIN public.rating_system rsy ON rsy.id = rs.rating_system_id
    WHERE prs.player_id = NEW.id
      AND rsy.sport_id = v_player_sport.sport_id
    ORDER BY rs.value DESC NULLS LAST
    LIMIT 1;

    IF v_player_skill IS NULL THEN
      RAISE LOG 'Zone auto-join: no rating for sport=% player=%, skipping',
        v_player_sport.sport_id, NEW.id;
      CONTINUE;
    END IF;

    IF v_player_skill = 'professional' THEN
      v_player_skill := 'advanced';
    END IF;

    INSERT INTO public.network_member (
      network_id, player_id, status, joined_at, request_type, role, added_by
    )
    SELECT
      n.id, NEW.id, 'active'::network_member_status, NOW(),
      'direct_add'::network_member_request_type, 'member', NULL
    FROM public.network n
    WHERE n.network_type_id = v_community_type_id
      AND n.zone = v_zone
      AND n.sport_id = v_player_sport.sport_id
      AND (n.skill_level = v_player_skill OR n.skill_level IS NULL)
      AND n.archived_at IS NULL
    ON CONFLICT (network_id, player_id) DO NOTHING;
  END LOOP;

  RAISE LOG 'Zone auto-join completed: player_id=%, zone=%', NEW.id, v_zone;
  RETURN NEW;
END;
$$;

-- =============================================================================
-- STEP 6: Backfill existing onboarded players who now resolve to a rive zone.
-- Additive only: island addresses never fall in an off-island polygon, so no
-- existing membership needs removing.
-- =============================================================================
DO $backfill$
DECLARE
  v_community_type_id UUID;
  v_inserted INTEGER;
BEGIN
  SELECT id INTO v_community_type_id FROM public.network_type WHERE name = 'community';

  WITH player_zone AS (
    SELECT p.id AS player_id, public.derive_zone_from_location(p.location) AS zone
    FROM public.profile pr
    JOIN public.player p ON p.id = pr.id
    WHERE pr.onboarding_completed = TRUE
  ),
  inserted AS (
    INSERT INTO public.network_member (network_id, player_id, status, joined_at, request_type, role)
    SELECT n.id, pz.player_id, 'active'::network_member_status, NOW(),
           'direct_add'::network_member_request_type, 'member'
    FROM player_zone pz
    JOIN public.player_sport ps ON ps.player_id = pz.player_id
    JOIN public.network n
      ON n.network_type_id = v_community_type_id
     AND n.zone = pz.zone
     AND n.sport_id = ps.sport_id
     AND n.skill_level IS NULL
     AND n.archived_at IS NULL
    WHERE pz.zone IN ('rive_nord','rive_sud')
    ON CONFLICT (network_id, player_id) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_inserted FROM inserted;

  RAISE NOTICE 'Rive backfill: % memberships inserted', v_inserted;
END
$backfill$;
